#!/usr/bin/env bash
# Release R99 — tasks 200 (A-27), 201 (A-28), 202 (A-26). diff origin/main(a194563)..HEAD, xz+base64, sha256-guarded.
set -euo pipefail
T=$(mktemp -d)
base64 -d > "$T/d.xz" <<'B64'

B64
xz -d -c "$T/d.xz" > "$T/d.diff"
echo "f3b17c23f1c440be1025dec9b7c3a067778461129d75b9a5d04e3c13e9f833a5  $T/d.diff" | sha256sum -c -
git apply --binary "$T/d.diff"
